// D. Overhead Industrial Gantry Crane with Lattice Truss & Suspended Power Reactor
const gantryGroup = new THREE.Group();

// Main dual steel rails
const railMat = materials.structuralSteel;
const gantryRail1 = new THREE.Mesh(new THREE.BoxGeometry(HANGAR_WIDTH - 6, 1.2, 0.8), railMat);
gantryRail1.position.set(0, HANGAR_HEIGHT - 3.8, -3.8);
gantryGroup.add(gantryRail1);

const gantryRail2 = new THREE.Mesh(new THREE.BoxGeometry(HANGAR_WIDTH - 6, 1.2, 0.8), railMat);
gantryRail2.position.set(0, HANGAR_HEIGHT - 3.8, -6.2);
gantryGroup.add(gantryRail2);

// Hazard Yellow Undercarriage Plate
const underPlateGeo = new THREE.BoxGeometry(HANGAR_WIDTH - 8, 0.35, 3.2);
const underPlate = new THREE.Mesh(underPlateGeo, materials.hazardYellow);
underPlate.position.set(0, HANGAR_HEIGHT - 4.5, -5.0);
gantryGroup.add(underPlate);

// Cross Truss Braces
for (let gx = -HANGAR_WIDTH / 2 + 6; gx <= HANGAR_WIDTH / 2 - 6; gx += 5.5) {
  const crossTruss = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.8, 2.6), materials.structuralSteel);
  crossTruss.position.set(gx, HANGAR_HEIGHT - 3.8, -5.0);
  crossTruss.rotation.x = Math.PI / 4;
  gantryGroup.add(crossTruss);
}

// Trolley & Hoist Unit
const trolleyGeo = new THREE.BoxGeometry(4.8, 1.4, 3.8);
const trolley = new THREE.Mesh(trolleyGeo, materials.hullDark);
trolley.position.set(-8, HANGAR_HEIGHT - 5.1, -5.0);
gantryGroup.add(trolley);

// Steel Suspension Cables
const cableGeo = new THREE.CylinderGeometry(0.04, 0.04, 5.0);
const cable1 = new THREE.Mesh(cableGeo, materials.structuralSteel);
cable1.position.set(-9.4, HANGAR_HEIGHT - 8.2, -5.0);
gantryGroup.add(cable1);

const cable2 = cable1.clone();
cable2.position.x = -6.6;
gantryGroup.add(cable2);

// Suspended Sci-Fi Power Cell / Reactor Core
const cargoGroup = new THREE.Group();
cargoGroup.position.set(-8, HANGAR_HEIGHT - 11.5, -5.0);

const cargoHull = new THREE.Mesh(new THREE.BoxGeometry(3.8, 2.4, 2.8), materials.hullMid);
cargoHull.castShadow = true;
cargoGroup.add(cargoHull);

// Glowing Power Band
const cargoBand = new THREE.Mesh(new THREE.BoxGeometry(3.88, 0.35, 2.88), materials.emissiveCyan);
cargoGroup.add(cargoBand);

// Corner Shock Bumpers
for (let bx = -1.9; bx <= 1.9; bx += 3.8) {
  for (let bz = -1.4; bz <= 1.4; bz += 2.8) {
    const bumper = new THREE.Mesh(new THREE.BoxGeometry(0.3, 2.5, 0.3), materials.hazardYellow);
    bumper.position.set(bx, 0, bz);
    cargoGroup.add(bumper);
  }
}

gantryGroup.add(cargoGroup);
scene.add(gantryGroup);

// Taxiway Guide Lines on Floor (Connecting runway to docking bays)
const taxiwayMat = new THREE.MeshStandardMaterial({
  color: 0x00f0ff,
  emissive: 0x00f0ff,
  emissiveIntensity: 1.5,
  roughness: 0.3
});

for (let i = 0; i < 3; i++) {
  const dockZ = -30 + i * 28;
  // Line from X = -8 to X = -24
  const taxiLineLeft = new THREE.Mesh(new THREE.PlaneGeometry(16, 0.25), taxiwayMat);
  taxiLineLeft.rotation.x = -Math.PI / 2;
  taxiLineLeft.position.set(-16, 0.22, dockZ);
  scene.add(taxiLineLeft);

  // Line from X = 8 to X = 24
  const taxiLineRight = new THREE.Mesh(new THREE.PlaneGeometry(16, 0.25), taxiwayMat);
  taxiLineRight.rotation.x = -Math.PI / 2;
  taxiLineRight.position.set(16, 0.22, dockZ);
  scene.add(taxiLineRight);
}

